import { setLoginUser, clearLoginUser } from '../src/utils/request'
import type { PortalListType } from '../src/types/portal'

/**
 * 门户数据服务回归测试：单测环境固定 VITE_DATA_MODE=demo（不发网络请求），
 * 断言真实接口不可用时首页/我的/列表/详情都稳定回退到设计稿静态数据。
 */
describe('portal demo fallback', () => {
  it('demo 模式不发请求且保留设计稿内容', async () => {
    expect(usePortalApi()).toBe(false)
    const home = await fetchHome()
    expect(home.notice.title).toBe(SEED_HOME.notice.title)
    expect(home.banner.title).toContain('智慧物业')
    expect(home.news.length).toBeGreaterThan(0)
    expect(home.tabs).toEqual([...PORTAL_TABS])
    const mine = await fetchMine()
    expect(mine.user.name).toBe(SEED_MINE.user.name)
    expect(mine.user.loginName).toBe(SEED_MINE.user.loginName)
    expect(mine.user.verified).toBe(true)
  })

  it('各类型列表与详情都回退到静态条目', async () => {
    const types: PortalListType[] = ['notice', 'news', 'study', 'message', 'task']
    for (const type of types) {
      const res = await fetchList(type, 1, 10, PORTAL_TABS[0])
      expect(res.items.length).toBe(seedList(type, PORTAL_TABS[0]).length)
      expect(res.items[0].title.length).toBeGreaterThan(0)
    }
    const detail = await fetchDetail('notice', 'seed-notice-1')
    expect(detail.title).toContain('紧急通知')
    expect(detail.content).toContain('<div')
  })
})

