    expect(usePortalApi()).toBe(false)
    const home = await fetchHome()
    expect(home.notice.title).toBe('')
    expect(home.todoCount).toBe(0)
    expect(home.news).toEqual([])
    expect((await fetchList('task', 1, 10)).items).toEqual([])
    expect(apiCall).not.toHaveBeenCalled()

    vi.stubEnv('VITE_API_BASE_URL', '/api')
    expect(usePortalApi()).toBe(false)
    expect((await fetchList('notice', 1, 10)).items).toEqual([])
    expect(apiCall).not.toHaveBeenCalled()
  })

  it('已配置且登录时请求远程列表，并映射空响应', async () => {
    vi.stubEnv('VITE_API_BASE_URL', '/api')
    vi.stubEnv('VITE_AUTH_BASE_URL', '')
    setLoginUser({ nickName: '测试用户', userName: 'tester', userId: '1' })
    const apiCall = vi.spyOn(portalApi, 'appMsg').mockResolvedValue({ total: 0, rows: [] })
    expect(usePortalApi()).toBe(true)
    const result = await fetchList('notice', 2, 5)
    expect(apiCall).toHaveBeenCalledWith({ pageNum: 2, pageSize: 5, msgType: '' })
    expect(result).toEqual({ items: [], total: 0, hasMore: false })
  })

  it('远程请求失败时向调用方传播错误', async () => {
    vi.stubEnv('VITE_API_BASE_URL', '/api')
    vi.stubEnv('VITE_AUTH_BASE_URL', '')
    setLoginUser({ nickName: '测试用户', userName: 'tester', userId: '1' })
    vi.spyOn(portalApi, 'appMsg').mockRejectedValue(new Error('network unavailable'))
    await expect(fetchList('notice', 1, 10)).rejects.toThrow('network unavailable')
  })
})

