  let resolveSave: ((value: unknown) => void) | undefined
  const request = vi.spyOn(requestModule, 'request').mockImplementation(path => {
    if (path.endsWith('/inspection/save')) return new Promise(resolve => { resolveSave = resolve })
    if (path.endsWith('/inspection/submit')) return Promise.resolve(undefined)
    return Promise.reject(new Error('detail unavailable'))
  })
  const store = createFloodStore(storage)()
  const values = { eventId: 'event-1', complexId: 'complex-1', items: [{ templateItemId: 'item-1', fillType: '1', value: '正常' }] }
  const pending = store.submitInspection('pre', values)
